# food-picture-01: "Tiny Chefs, Giant Feast" — writes the food image to /output/entry.png.
# Three tiny chefs grill one giant glistening steak: a single hero dish fills
# the frame, glossy with sauce, steam rising, miniature chefs in white hats
# tending it under warm golden light. The image bytes are embedded below as
# base64 (one single line, 422,068 characters for a 1024x1024 JPEG of 316,551
# bytes) so the program is self-contained: no bundled image file, no network,
# no model calls, no randomness. Every run writes the same bytes.
# Deterministic, Python 3.13 standard library only. Output honours
# MAKEFUN_OUTPUT_DIR when set, defaulting to /output.
import base64
import os

DATA = ""


def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    with open(os.path.join(out_dir, "entry.png"), "wb") as f:
        f.write(base64.b64decode(DATA))


if __name__ == "__main__":
    main()
